package com.example.examauth.util; import javax.crypto.Cipher; import javax.crypto.spec.GCMParameterSpec; import javax.crypto.spec.SecretKeySpec; import javax.crypto.SecretKey; import java.security.SecureRandom; import java.util.Base64; import java.nio.charset.StandardCharsets; public class AESGcmUtil { private static final int IV_LEN = 12; private static final int TAG_LEN_BIT = 128; private static final SecureRandom SECURE_RANDOM = new SecureRandom(); public static String encrypt(SecretKey key, String plaintext, byte[] aad) throws Exception { byte[] iv = new byte[IV_LEN]; SECURE_RANDOM.nextBytes(iv); Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding"); GCMParameterSpec spec = new GCMParameterSpec(TAG_LEN_BIT, iv); cipher.init(Cipher.ENCRYPT_MODE, key, spec); if(aad!=null) cipher.updateAAD(aad); byte[] cipherText = cipher.doFinal(plaintext.getBytes(StandardCharsets.UTF_8)); byte[] out = new byte[iv.length + cipherText.length]; System.arraycopy(iv,0,out,0,iv.length); System.arraycopy(cipherText,0,out,iv.length,cipherText.length); return Base64.getUrlEncoder().withoutPadding().encodeToString(out); } public static String decrypt(SecretKey key, String b64Payload, byte[] aad) throws Exception { byte[] all = Base64.getUrlDecoder().decode(b64Payload); byte[] iv = new byte[IV_LEN]; System.arraycopy(all,0,iv,0,IV_LEN); byte[] cipherText = new byte[all.length - IV_LEN]; System.arraycopy(all,IV_LEN,cipherText,0,cipherText.length); Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding"); GCMParameterSpec spec = new GCMParameterSpec(TAG_LEN_BIT, iv); cipher.init(Cipher.DECRYPT_MODE, key, spec); if(aad!=null) cipher.updateAAD(aad); byte[] plain = cipher.doFinal(cipherText); return new String(plain, StandardCharsets.UTF_8); } }